from addlib import *
# ================= C24 completion popup =================
K=[
 ('planner.completion.title (invariato)',T(*[L('planner.completion.title',l) for l in LANGS])),
 ('planner.completion.line (invariato)',T(*[L('planner.completion.line',l) for l in LANGS])),
 ('planner.completion.share',T('Condividi il tuo planner','Share your planner','Partagez votre planner','Comparte tu planner','Teile deinen Planner')),
 ('planner.completion.sound',T('Suono','Sound','Son','Sonido','Ton')),
 ('planner.completion.soundHint',T('Un breve suono di festa. Spento di default.','A short celebration sound. Off by default.','Un court son de fête. Désactivé par défaut.','Un breve sonido de celebración. Desactivado por defecto.','Ein kurzer Feierton. Standardmäßig aus.')),
]
CONF_COL=['var(--accent)','var(--highlight)','var(--ink)','var(--accent)','var(--highlight)','var(--ink)','var(--highlight)','var(--accent)']
def confetti(n=24,static=True):
    out=''
    for i in range(n):
        x=(i*37)%100; y=(i*53)%22; r=(i*47)%360; c=CONF_COL[i%len(CONF_COL)]
        out+=f'<span style="position:absolute;left:{x}%;top:{y}%;width:8px;height:14px;background:{c};transform:rotate({r}deg);border-radius:2px;opacity:.9"></span>'
    return f'<div aria-hidden="true" style="position:absolute;inset:0;overflow:hidden;pointer-events:none">{out}</div>'
def comp_body(sound=False,big=False):
    sw=f'<div class="switch"><span>{dict(K)["planner.completion.sound"]["it"]}</span><label class="switch__control"><input class="switch__input" type="checkbox" role="switch"{" checked=\"checked\"" if sound else ""} aria-label="{dict(K)["planner.completion.sound"]["it"]}"/><span class="switch__track" aria-hidden="true"></span></label></div>'
    h=(f'<p style="margin:0;font-family:var(--font-display);font-size:var(--fs-hero);line-height:.9;color:var(--highlight)">100%</p>' if big else '')
    return (f'<div style="position:relative;display:flex;flex-direction:column;gap:var(--sp-3);align-items:flex-start">{confetti()}<div style="position:relative;display:flex;flex-direction:column;gap:var(--sp-3);align-items:flex-start;width:100%">{h}<p style="margin:0;font-size:var(--fs-title);font-weight:800">{L("planner.completion.line")}</p>'
            f'{btn("primary",dict(K)["planner.completion.share"]["it"],"lg","","share-2")}{sw}<p class="muted" style="margin:0">{dict(K)["planner.completion.soundHint"]["it"]}</p></div></div>')
def comp_banner(): return tstack(f'<div class="toast toast--info" role="status" style="position:relative"><span class="toast__badge" aria-hidden="true">{icon("check")}</span><div class="toast__text"><strong>{L("planner.completion.title")}</strong><span>{L("planner.completion.line")}</span></div></div>')
RM=modal(L('planner.completion.title'),f'<div style="display:flex;flex-direction:column;gap:var(--sp-3);align-items:flex-start"><span class="dc-chip k2" style="background:var(--highlight);color:var(--ink-static)">100%</span><p style="margin:0;font-size:var(--fs-title);font-weight:800">{L("planner.completion.line")}</p>{btn("primary",dict(K)["planner.completion.share"]["it"],"lg","","share-2")}</div>')
add('Planner',
 block('Nuova funzione · popup di completamento (al posto dell\'adesivo)',PROP,'<b>Cosa cambia:</b> quando il planner arriva al 100% non compare più l\'adesivo sotto “I tuoi progressi” (<code>CompletionSticker</code>) ma un popup, una sola volta (flag <code>mcu-planner-completed-seen</code>, come oggi). Dopo la chiusura la scheda dei progressi mostra solo il 100% in <code>--highlight</code>. <b>Coriandoli:</b> 24-32 pezzi (8×14px) nei colori <code>--accent</code>, <code>--highlight</code>, <code>--ink</code>, che cadono per 1,8 s dalla parte alta del popup con rotazione e fine a opacità 0; non catturano il focus né i clic (<code>pointer-events: none</code>, <code>aria-hidden</code>). <b>Movimento ridotto:</b> nessun coriandolo; resta il popup con il chip 100% <code>--highlight</code> (come l\'adesivo di oggi). <b>Suono (sì, ma opzionale):</b> interruttore “Suono” <b>spento di default</b> dentro il popup; attivandolo parte una volta un breve suono (&lt; 1 s, tono basso) come conferma e la scelta si salva (<code>mcu-planner-sound</code>, nuova riga nell\'inventario privacy); mai riprodotto all\'apertura se non attivato da te. Il suono non è informazione: tutto ciò che dice è anche scritto (WCAG 1.4.2, 1.2). Vincolo di accessibilità: nessun suono automatico.',
  vgrid(
   vcard('A','Popup (Modal) con coriandoli e azione “Condividi”',both('420px',modal(L('planner.completion.title'),comp_body(False),close=True),'Suono spento'),'Modal md: titolo <code>planner.completion.title</code>, riga <code>planner.completion.line</code>, azione primaria “Condividi il tuo planner”, interruttore Suono. La X chiude (popup di contenuto: nessun “Chiudi”).',['Suono spento (predefinito)','Suono acceso: stesso popup, interruttore attivo','Movimento ridotto: senza coriandoli (sotto)','Chiusura: X, Esc o sfondo; focus sul titolo all\'apertura'],['Un momento chiaro e raro','Porta a un\'azione utile (condividere)','Si legge anche senza movimento'],['Interrompe il flusso: un clic per chiuderlo'],True),
   vcard('B','Popup grande con “100%” in display',both('420px',modal(L('planner.completion.title'),comp_body(False,True),close=True),'Con 100% grande'),'Come A ma con il 100% grande in carattere display <code>--highlight</code> sopra la riga, che ripete la scheda dei progressi.',['Come A','Su mobile il 100% scala con il foglio'],['Più impatto visivo'],['Ripete il dato già in pagina','Più alto: su schermi bassi richiede scorrimento']),
   vcard('C','Solo toast con coriandoli brevi',both('420px',comp_banner(),'Toast (1 s di coriandoli)'),'Nessun popup: un toast “Multiverso completato” con 1 s di coriandoli ai lati; si chiude da solo.',['Toast info di 4 s','Movimento ridotto: solo il toast'],['Non interrompe niente'],['Per un traguardo di questo peso è poco','Nessuno spazio per condividere né per il suono'])
  )+why('<b>Variante A.</b> Il completamento è un evento raro e voluto: merita un momento, ma deve essere breve e portare a qualcosa (condividere). B ripete il 100%; C è troppo leggera. Suono: sì, ma solo come interruttore spento di default dentro il popup.')
  +'<div class="dc-fl">Movimento ridotto (variante A)</div>'+both('420px',RM,'Senza coriandoli')
  +'<div class="dc-fl">Suono acceso (variante A)</div>'+both('420px',modal(L('planner.completion.title'),comp_body(True),close=True),'Interruttore attivo')
  +'<div class="dc-fl">Testi nelle 5 lingue</div>'+txt(K)
  +pd([['Completamento','adesivo sotto “I tuoi progressi”','popup una volta (variante A); l\'adesivo si toglie','CompletionSticker.tsx; PlannerSummary.tsx'],['Inventario privacy','<code>mcu-planner-completed-seen</code>','+ <code>mcu-planner-sound</code> (preferenza suono)','Privacy (cookiePage.*)']])),
)
# ================= C30 guide =================
G=[
 ('planner.guide.title (invariato)',T(*[L('planner.guide.title',l) for l in LANGS])),
 ('planner.guide.startTerm',T('Da dove iniziare','Where to start','Par où commencer','Por dónde empezar','Wo anfangen')),
 ('planner.guide.startText',T('Parti dal primo titolo e vai in ordine: è l’ordine di uscita, il migliore per una prima visione. Spunta ogni titolo che hai visto: il planner ti mostra il prossimo.','Start with the first title and go in order: it is release order, the best one for a first watch. Tick every title you have seen: the planner shows you the next one.','Commencez par le premier titre et suivez l’ordre : c’est l’ordre de sortie, le meilleur pour un premier visionnage. Cochez chaque titre vu : le planner vous montre le suivant.','Empieza por el primer título y sigue el orden: es el orden de estreno, el mejor para una primera vez. Marca cada título que hayas visto: el planner te muestra el siguiente.','Beginne mit dem ersten Titel und folge der Reihenfolge: Es ist die Erscheinungsfolge, ideal für das erste Mal. Hake jeden gesehenen Titel ab: Der Planner zeigt dir den nächsten.')),
 ('planner.guide.orderTerm2',T('Vuoi seguire la storia?','Want to follow the story?','Envie de suivre l’histoire ?','¿Quieres seguir la historia?','Lieber der Geschichte folgen?')),
 ('planner.guide.orderText2',T('Alcuni titoli, come Captain America: The First Avenger e Captain Marvel, sono ambientati nel passato. Per vederli al loro posto nella storia scegli «{chrono}».','Some titles, like Captain America: The First Avenger and Captain Marvel, are set in the past. To see them in story order, choose “{chrono}”.','Certains titres, comme Captain America: The First Avenger et Captain Marvel, se déroulent dans le passé. Pour les voir à leur place dans l’histoire, choisissez « {chrono} ».','Algunos títulos, como Captain America: The First Avenger y Captain Marvel, transcurren en el pasado. Para verlos en su lugar de la historia, elige «{chrono}».','Einige Titel, etwa Captain America: The First Avenger und Captain Marvel, spielen in der Vergangenheit. Um sie in der Reihenfolge der Handlung zu sehen, wähle „{chrono}“.')),
 ('planner.guide.alternateText2',T('I titoli con l’etichetta «{tag}», come X-Men ’97 e What If…?, raccontano universi paralleli: non servono per seguire la storia principale, guardali quando vuoi. Non ti interessano? Spegni «{filter}» nei filtri.','Titles tagged “{tag}”, like X-Men ’97 and What If…?, tell parallel-universe stories: you do not need them for the main story, watch them whenever you like. Not interested? Turn off “{filter}” in the filters.','Les titres marqués « {tag} », comme X-Men ’97 et What If…?, racontent des univers parallèles : ils ne sont pas nécessaires à l’histoire principale, regardez-les quand vous voulez. Pas intéressé ? Désactivez « {filter} » dans les filtres.','Los títulos con la etiqueta «{tag}», como X-Men ’97 y What If…?, cuentan universos paralelos: no hacen falta para seguir la historia principal, velos cuando quieras. ¿No te interesan? Desactiva «{filter}» en los filtros.','Titel mit dem Etikett „{tag}“, etwa X-Men ’97 und What If…?, erzählen Parallelwelten: Für die Haupthandlung sind sie nicht nötig, schau sie, wann du willst. Kein Interesse? Schalte „{filter}“ in den Filtern aus.')),
 ('planner.guide.help',T('Come leggere il planner','How to read the planner','Comment lire le planner','Cómo leer el planner','So liest du den Planner')),
 ('planner.guide.callout',T('Prima volta qui? Scopri come leggere il planner.','First time here? Learn how to read the planner.','Première fois ici ? Découvrez comment lire le planner.','¿Primera vez aquí? Descubre cómo leer el planner.','Zum ersten Mal hier? So liest du den Planner.')),
 ('planner.guide.calloutOpen',T('Leggi','Read','Lire','Leer','Lesen')),
 ('planner.guide.calloutDismiss',T('Non ora','Not now','Pas maintenant','Ahora no','Nicht jetzt')),
]
def gd(k,lang='it'):
    s=dict(G)[k][lang]
    return esc(s.replace('{chrono}',L('planner.order.chronological',lang)).replace('{tag}',L('planner.tags.alternate',lang)).replace('{filter}',L('planner.filters.showAlternate',lang)))
def guide_body(lang='it'):
    return (f'<div class="planner-guide__items"><div><h3>{gd("planner.guide.startTerm",lang)}</h3><p>{gd("planner.guide.startText",lang)}</p></div><div><h3>{gd("planner.guide.orderTerm2",lang)}</h3><p>{gd("planner.guide.orderText2",lang)}</p></div>'
            f'<div><h3>{L("planner.guide.alternateTerm",lang)}</h3><p>{gd("planner.guide.alternateText2",lang)}</p></div></div>')
helpbtn=btn('soft','','','','circle-help','aria-label="'+dict(G)['planner.guide.help']['it']+'"')
tool=f'<div style="display:flex;gap:var(--sp-2);align-items:center;flex-wrap:wrap;position:relative"><span class="muted">… ricerca e filtri …</span>{helpbtn}</div>'
callout=f'<div class="panel-surface" role="status" style="display:flex;gap:var(--sp-3);align-items:center;flex-wrap:wrap;border-radius:var(--r-md);padding:var(--sp-3) var(--sp-4);box-shadow:var(--shadow-pop);max-width:22rem"><span>{gd("planner.guide.callout")}</span>{btn("panel",gd("planner.guide.calloutOpen"),"sm")}{btn("panel",gd("planner.guide.calloutDismiss"),"sm")}</div>'
panel=f'<div class="dc-pad" style="background:var(--surface);border-radius:var(--r-md)"><div style="display:flex;justify-content:space-between;align-items:center"><h2 class="phase__name" style="margin:0">{gd("planner.guide.help")}</h2>{btn("panel","","sm","","x","aria-label=\""+L("common.close")+"\"")}</div>{guide_body()}</div>'
add('Planner',
 block('Nuova funzione · “Come leggere il planner”: da blocco in fondo a pulsante “?”',PROP,'<b>Oggi:</b> un accordion “Come leggere il planner” (<code>PlannerGuide</code>) in fondo alla pagina, prima del footer: aperto solo se non ci sono titoli visti e lo schermo è da 40em in su (non verificato in <code>PlannerGuide.tsx</code>), quindi chi ne ha bisogno non lo vede su mobile e chi lo ha già letto lo trova ogni volta. <b>Importanza:</b> bassa. Il planner si usa anche senza: due regole (ordine, continuità alternativa) e un\'idea d\'avvio. <b>Decisione:</b> si toglie il blocco dal fondo; si aggiunge un pulsante “?” (<code>circle-help</code>, soft, 44px, <code>aria-label</code> “Come leggere il planner”) nella barra sopra la lista, sempre visibile; alla <b>prima visita</b> (registrati o no, flag <code>mcu-planner-guide-seen</code>, nuovo, nell\'inventario privacy) compare una volta sola un invito non bloccante accanto al “?”. Testo rivisto: tre voci in ordine d\'uso (da dove iniziare, storia o uscita, continuità alternativa), frasi più corte, azione prima dell\'eccezione.',
  vgrid(
   vcard('A','“?” + popup; alla prima visita il popup si apre da solo',both('420px',modal(gd('planner.guide.help'),guide_body(),close=True),'Popup'),'Il “?” apre un Modal; alla prima visita lo stesso popup si apre da solo, una volta.',['Prima visita: si apre da solo','Visite successive: solo col “?”','Chiusura: X, Esc, sfondo','Flag salvato alla chiusura'],['Tutti la leggono'],['Interrompe la prima impressione: il popup copre il planner, ancora sconosciuto']),
   vcard('B','“?” + popup; alla prima visita un invito accanto al “?”',both('420px',f'<div style="display:flex;flex-direction:column;gap:var(--sp-3);align-items:flex-start">{tool}{callout}</div>','Invito alla prima visita'),'Il “?” apre il popup (come A). Alla prima visita, dopo il disegno della pagina, compare un invito <code>panel-surface</code> con “Leggi” e “Non ora”, ancorato al “?”. Si chiude da solo alla prima interazione con la pagina o con “Non ora”; non si ripresenta.',['Prima visita: invito visibile','“Leggi”: apre il popup e salva il flag','“Non ora”: salva il flag','Visite successive: nessun invito','Annunciato come <code>role="status"</code>'],['Non blocca nulla','Chi non lo vuole lo ignora e basta','Il popup resta a richiesta'],['Un invito in più da disegnare nelle 5 lingue','Può passare inosservato'],True),
   vcard('C','“?” + pannello laterale (foglio su mobile)',both('420px',panel,'Pannello'),'Il “?” apre un pannello laterale (desktop) o un foglio dal basso (mobile) che non copre il planner; alla prima visita il pannello si apre da solo.',['Desktop: pannello da 20rem a destra','Mobile: foglio dal basso','Prima visita: si apre da solo'],['Si legge guardando il planner'],['È un componente nuovo (non c\'è un pannello laterale nell\'app)','Su mobile coincide con un popup'])
  )+why('<b>Variante B.</b> La guida è utile ma secondaria: non deve interrompere chi arriva per la prima volta e ancora non sa cosa guardare. L\'invito è visibile una volta, si può ignorare, e il “?” resta sempre lì. A interrompe, C introduce un componente che nell\'app non esiste.')
  +'<div class="dc-fl">“?” nella barra (stati: riposo, focus)</div>'+both('420px',f'<div style="display:flex;gap:var(--sp-3)">{helpbtn}{btn("soft","","","is-focus","circle-help","aria-label=\""+dict(G)["planner.guide.help"]["it"]+"\"")}</div>','Riposo · focus')
  +'<div class="dc-fl">Popup nelle 5 lingue: testi nuovi e rivisti</div>'+txt(G,chrono=L('planner.order.chronological'),tag=L('planner.tags.alternate'),filter=L('planner.filters.showAlternate'))
  +pd([['Posizione','accordion in fondo alla pagina','pulsante “?” sopra la lista + popup','PlannerGuide.tsx; Planner.tsx; PlannerFilters.tsx'],['Prima visita','aperto solo senza titoli visti e da 40em','invito non bloccante una volta (flag <code>mcu-planner-guide-seen</code>)','Privacy (cookiePage.*)'],['Testo','2 voci lunghe','3 voci brevi in ordine d\'uso','locales <code>planner.guide.*</code>']])),
)
